// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint128 a1, uint128 a2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(a1 != a2); // sums differing keeps the distinction meaningful
        vm.assume(uint256(a1) + uint256(a2) <= type(uint256).max); // admissibility of require

        vm.deal(actor, uint256(a1) + uint256(a2));

        vm.prank(actor);
        c.addToBalance{value: a1}();
        vm.prank(actor);
        c.addToBalance{value: a2}();

        // Rule: balance after two deposits equals their sum (deposits accumulate).
        assertTrue(c.getBalance(actor) == uint256(a1) + uint256(a2));
    }
}
